class TestPkce:
    @staticmethod
    def _challenge_of(verifier: str) -> str:
        digest = hashlib.sha256(verifier.encode("ascii")).digest()
        return base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")

    def test_bhv_authoauthtwoauthcode_023_the_authorization_url_carries_an_s256_challenge(
        self,
    ) -> None:
        params = parse_qs(
            urlparse(_create_authenticator().build_authorization_url()).query
        )

        assert params["code_challenge_method"] == ["S256"]
        assert re.fullmatch(r"[A-Za-z0-9_-]{43}", params["code_challenge"][0])
        assert "nonce" not in params

    def test_bhv_authoauthtwoauthcode_008_the_code_exchange_proves_the_challenge_with_the_verifier(
        self,
    ) -> None:
        auth = _create_authenticator()
        mock_client = MagicMock()
        mock_client.send_request.return_value = _code_reply(
            access_token="at", expires_in=3600
        )
        auth.set_api_client(mock_client)
        params = parse_qs(urlparse(auth.build_authorization_url()).query)

        auth.exchange_code("c")

        verifier = _form_of(mock_client.send_request.call_args)["code_verifier"][0]
        assert len(verifier) == 43
        assert re.fullmatch(r"[A-Za-z0-9_-]+", verifier)
        assert self._challenge_of(verifier) == params["code_challenge"][0]

    def test_bhv_authoauthtwoauthcode_009_every_authorization_url_gets_a_new_verifier(
        self,
    ) -> None:
        auth = _create_authenticator()

        first = parse_qs(urlparse(auth.build_authorization_url()).query)[
            "code_challenge"
        ]
        second = parse_qs(urlparse(auth.build_authorization_url()).query)[
            "code_challenge"
        ]

        assert first != second

    def test_bhv_authoauthtwoauthcode_001_an_exchange_without_a_built_url_sends_no_verifier(
        self,
    ) -> None:
        auth = _create_authenticator()
        mock_client = MagicMock()
        mock_client.send_request.return_value = _code_reply(
            access_token="at", expires_in=3600
        )
        auth.set_api_client(mock_client)

        auth.exchange_code("c")

        assert "code_verifier" not in _form_of(mock_client.send_request.call_args)

    def test_bhv_auth_020_the_verifier_is_spent_by_a_successful_exchange(self) -> None:
        auth = _create_authenticator()
        mock_client = MagicMock()
        mock_client.send_request.return_value = _code_reply(
            access_token="at", expires_in=3600
        )
        auth.set_api_client(mock_client)
        auth.build_authorization_url()
        auth.exchange_code("a")

        auth.exchange_code("b")

        assert "code_verifier" in _form_of(mock_client.send_request.call_args_list[0])
        assert "code_verifier" not in _form_of(
            mock_client.send_request.call_args_list[1]
        )


class TestInvalidateAccessToken:
    def test_bhv_authoauthtwoauthcode_016_a_dropped_token_is_replaced_by_a_refresh_and_the_refresh_token_is_kept(
        self,
    ) -> None:
        auth = _create_authenticator()
        mock_client = MagicMock()
        mock_client.send_request.side_effect = [
            _code_reply(access_token="t1", refresh_token="r1", expires_in=3600),
            _code_reply(access_token="t2", expires_in=3600),
        ]
        auth.set_api_client(mock_client)
        auth.exchange_code("a")
        assert auth.get_auth_headers() == {"Authorization": "Bearer t1"}

        auth.invalidate_access_token()

        assert auth.get_auth_headers() == {"Authorization": "Bearer t2"}
        refresh = _form_of(mock_client.send_request.call_args_list[1])
        assert refresh["grant_type"] == ["refresh_token"]
        assert refresh["refresh_token"] == ["r1"]


class TestPkceAppendixB:
    def test_bhv_auth_008_the_s256_challenge_matches_the_rfc_7636_appendix_b_value(
        self,
    ) -> None:
        authenticator = _create_authenticator()

        with patch(
            "secrets.token_urlsafe",
            return_value="dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk",
        ):
            url = authenticator.build_authorization_url()

        assert "code_challenge=E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM" in url
